                NameTree.clashing(taken, p.name(), byPerson.getOrDefault(p.id(), List.of())), origins.get(p.id()),
                tags.get(p.id()), statements.getOrDefault(p.id(), List.of()),
                flags.get(p.id())))
                .toList());
    }
}

