import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
 * today, null when they have none then;
 * `contact` their contact (trimmed, lower-cased), null when they have none. `clashing` is whether another sheet of
 * the sheet's tree (its ancestors and descendants) uses their name or any of their aliases as a name or alias.
 * `origin` is the sheet they were transferred from, null when they were not transferred here. `pastRetirements` are
 * the retirements they were unretired from, oldest first: a claim dated after one's from and before its to is refused.
 * `tags` are their tags, sorted (none: empty). `statements` are their statements still standing, each as
 * `<statement date> <due-total>`, oldest first. `flag` is the reason of their flag while it is in force on the sheet's
 * today, "" otherwise.
 */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  terms: number | null;
  contact: string | null;
  clashing: boolean;
  origin: string | null;
  pastRetirements: { from: string; to: string }[];
  tags: string[];
  statements: string[];
  flag: string;
};

